  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Calculate the final trip price for a booking after applying membership discount rules.
   * Algorithm:
   * 1. If customer is null, bookingTime is null/empty, or this trip price is invalid, return the original trip price.
   * 2. If customer has no membershipPackage, return the original trip price.
   * 3. If membershipPackage does not contain Award.DISCOUNTS, return the original trip price.
   * 4. If the booking is made at least 24 hours before this trip's departure time, apply a 20 percent discount:
   *    discountedPrice = price * 0.8
   * 5. Otherwise, return the original trip price.
   * 6. Round the result to one decimal place before returning.
   * Related Features:
   * Trip.price, Trip.departureTime, Trip.calculateDiscountedPrice
   * Customer.membershipPackage
   * MembershipPackage.awards, MembershipPackage.hasAward
   * Award.DISCOUNTS
   * Related Classes: Trip, Customer, MembershipPackage, Award
   * Input:
   * customer : Customer
   * - Customer for whom the price is being calculated.
   * bookingTime : String
   * - Booking time; must be comparable with the trip departure time.
   * Output:
   * double
   * - Final trip price after discount evaluation.
   * - Rounded to one decimal place.
   * Pre-condition:
   * - This trip exists.
   * - This trip price is defined.
   * - customer may be null; if null, no discount is applied.
   * - bookingTime may be null; if null, no discount is applied.
   * Post-condition:
   * - No model state is modified.
   * - The returned value is the discounted price only when the customer has DISCOUNTS reward
   *   and the booking is made at least 24 hours before departure; otherwise the original price is returned.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || bookingTime == null || bookingTime.length() == 0)
    {
      return Math.round(price * 10.0) / 10.0;
    }
    if (price < 0)
    {
      return Math.round(price * 10.0) / 10.0;
    }
    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null || !membershipPackage.hasAward(Award.DISCOUNTS))
    {
      return Math.round(price * 10.0) / 10.0;
    }
    if (departureTime == null)
    {
      return Math.round(price * 10.0) / 10.0;
    }
    try
    {
      java.time.format.DateTimeFormatter formatter = java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
      java.time.LocalDateTime bookingDateTime = java.time.LocalDateTime.parse(bookingTime, formatter);
      java.time.LocalDateTime departureDateTime = java.time.LocalDateTime.parse(departureTime, formatter);
      if (java.time.Duration.between(bookingDateTime, departureDateTime).toHours() >= 24)
      {
        return Math.round((price * 0.8) * 10.0) / 10.0;
      }
    }
    catch (Exception e)
    {
      return Math.round(price * 10.0) / 10.0;
    }
    return Math.round(price * 10.0) / 10.0;
    
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Calculate points earned by the specified customer for bookings on this trip within a given month.
   * Algorithm:
   * 1. If customer is null or currentMonth is null, return 0.
   * 2. Iterate over this trip’s bookings.
   * 3. For each booking that belongs to customer and booking.isInMonth(currentMonth) is true,
   *    add booking.numberOfSeats * 5 to the total.
   * 4. Return the total points.
   * Related Features:
   * Trip.bookings
   * Booking.customer, Booking.bookingDate, Booking.numberOfSeats, Booking.isInMonth
   * Related Classes: Trip, Booking, Customer
   * Input:
   * customer : Customer
   * - Customer for whom points are calculated.
   * currentMonth : String
   * - Requested month token/format.
   * Output:
   * int
   * - Total points earned on this trip during the specified month.
   * Pre-condition:
   * - This trip exists.
   * - bookings collection is initialized.
   * Post-condition:
   * - No model state is modified.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || currentMonth == null)
    {
      return 0;
    }
    int total = 0;
    if (bookings != null)
    {
      for (Booking booking : bookings)
      {
        if (booking != null && customer.equals(booking.getCustomer()) && booking.isInMonth(currentMonth))
        {
          total += booking.getNumberOfSeats() * 5;
        }
      }
    }
    return total;
    
  }

