      java.time.format.DateTimeFormatter formatter = java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
      java.time.LocalDateTime thisDeparture = java.time.LocalDateTime.parse(departureTime, formatter);
      java.time.LocalDateTime thisArrival = java.time.LocalDateTime.parse(arrivalTime, formatter);
      java.time.LocalDateTime otherDeparture = java.time.LocalDateTime.parse(newDepartureTime, formatter);
      java.time.LocalDateTime otherArrival = java.time.LocalDateTime.parse(newArrivalTime, formatter);

      if (!thisDeparture.isBefore(thisArrival) || !otherDeparture.isBefore(otherArrival))
      {
        return false;
      }

      return thisDeparture.isBefore(otherArrival) && otherDeparture.isBefore(thisArrival);
